"""The fast-track seeded catalog fixture for manifest compile (FT-E2, FT-E3, FT-D3).

The committed seed bundles (A6: Tavily, Firecrawl, PubMed, agent-browser MCP, ...) are published
into an in-memory definition repository and projected for lexical search (no embeddings, no
provider). ``fast_track_seeds.json`` adds the rows the three owner manifests search for that
the production seeds do not carry yet (A7 skills, hook scripts, subagent profiles, the
agent-browser plugin, a remote PubMed endpoint for cursor_cloud, the Biotech ``kg_ingest`` tool
stand-in, assessments and deterministic executors). It is generated by :func:`build_rows`
(``python -m tests.fixtures.catalog.fast_track_catalog`` rewrites it) so every digest is real.
"""

from __future__ import annotations

import hashlib
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from tests.fixtures.capability_search_catalog import seeded_published

from mission_control.application.authoring.control_plane_repository import (
    DEFINITION_ADAPTER,
    InMemoryDefinitionRepository,
)
from mission_control.application.capabilities.capability_search import CapabilitySearchService
from mission_control.application.capabilities.capability_search_repository import (
    InMemoryCatalogSearchRepository,
)
from mission_control.application.capabilities.catalog_projection import (
    CatalogProjectionInput,
    CatalogProjector,
)
from mission_control.domain.authoring.canonical import sha256_digest
from mission_control.domain.authoring.contracts import (
    CapabilityDefinition,
    CapabilityKind,
    CatalogPayloadRef,
    DefinitionKind,
    ExactDefinitionRef,
    HookScriptDefinition,
    MCPServerDefinition,
    MCPToolDefinition,
    PluginDefinition,
    PublishedDefinition,
    SkillDefinition,
    SkillFileManifestEntry,
    SourceProvenance,
    SubagentProfileDefinition,
)
from mission_control.domain.capabilities.catalog_entry import capability_pin
from mission_control.domain.capabilities.hooks import HookEvent, HookInterpreter
from mission_control.domain.capabilities.host_support import (
    CapabilityHostSupport,
    HostProfileSupport,
    HostSupportStatus,
    LaneProfile,
)
from mission_control.domain.capabilities.plugins import (
    PluginManifest,
    PluginMember,
    PluginMemberRole,
)
from mission_control.domain.capabilities.subagents import SubagentProfile

HERE = Path(__file__).resolve().parent
SEEDS = HERE / "fast_track_seeds.json"
NOW = datetime(2026, 10, 7, tzinfo=UTC)
ALL_LANES = (LaneProfile.DEEP_AGENTS, LaneProfile.CURSOR_LOCAL, LaneProfile.CURSOR_CLOUD)


def _digest(text: str) -> str:
    return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()


def _status(supported: bool) -> HostSupportStatus:
    return HostSupportStatus.SUPPORTED if supported else HostSupportStatus.UNSUPPORTED


def _support(*lanes: LaneProfile) -> CapabilityHostSupport:
    return CapabilityHostSupport(
        profiles={
            lane: HostProfileSupport(
                status=HostSupportStatus.SUPPORTED
                if lane in lanes
                else HostSupportStatus.UNSUPPORTED
            )
            for lane in ALL_LANES
        }
    )


def _files(*paths: str) -> tuple[SkillFileManifestEntry, ...]:
    return tuple(
        SkillFileManifestEntry(path=path, digest=_digest(path), size_bytes=len(path))
        for path in paths
    )


def _provenance(identity: str, version: str) -> SourceProvenance:
    return SourceProvenance(
        source="belllabs",
        locator=f"repo://tests/fixtures/catalog/{identity}",
        upstream_identity=identity,
        upstream_version=version,
    )


def _skill(
    logical_id: str, title: str, description: str, *, version: str, lanes: tuple[LaneProfile, ...]
) -> SkillDefinition:
    name = logical_id.split(".", 1)[1]
    manifest = _digest(f"{logical_id}@{version}")
    return SkillDefinition(
        logical_id=logical_id,
        title=title,
        description=description,
        skill_name=name,
        frontmatter={"name": name, "description": description},
        body_summary=description,
        bundle_ref=CatalogPayloadRef(
            uri=f"repo://tests/fixtures/catalog/{logical_id}",
            digest=manifest,
            media_type="application/vnd.belllabs.skill-manifest+json",
            size_bytes=256,
        ),
        manifest_digest=manifest,
        file_manifest=_files("SKILL.md", "references/procedure.md"),
        source_provenance=_provenance(logical_id, version),
        review_status="approved",
        host_support=_support(*lanes),
    )


def _hook(
    logical_id: str,
    title: str,
    description: str,
    *,
    events: tuple[HookEvent, ...],
    lanes: tuple[LaneProfile, ...],
    fail_closed: bool = False,
) -> HookScriptDefinition:
    return HookScriptDefinition(
        logical_id=logical_id,
        title=title,
        description=description,
        events=events,
        fail_closed=fail_closed,
        file_manifest=_files("hook.py"),
        manifest_digest=_digest(logical_id),
        entrypoint="hook.py",
        interpreter=HookInterpreter.PYTHON,
        host_support=_support(*lanes),
    )


def _subagent(
    logical_id: str, title: str, description: str, *, lanes: tuple[LaneProfile, ...]
) -> SubagentProfileDefinition:
    return SubagentProfileDefinition(
        logical_id=logical_id,
        title=title,
        description=description,
        profile=SubagentProfile(
            name=logical_id.split(".", 1)[1],
            description=description,
            prompt=f"You are the {title}. Report findings; never edit files.",
            readonly=True,
        ),
        host_support=_support(*lanes),
    )


def _tool(logical_id: str, title: str, description: str) -> CapabilityDefinition:
    """Assessments and deterministic executors: governed tool capabilities."""

    return CapabilityDefinition(
        logical_id=logical_id,
        kind=DefinitionKind.TOOL,
        title=title,
        description=description,
        capability_kind=CapabilityKind.TOOL,
        maturity="qualified",
        attachment_targets=frozenset({"agent.main"}),
    )


def _published(definition: Any) -> PublishedDefinition:
    return PublishedDefinition(
        ref=ExactDefinitionRef(
            kind=definition.kind,
            logical_id=definition.logical_id,
            revision=1,
            digest=sha256_digest(definition),
        ),
        definition=definition,
        published_at=NOW,
        published_by="fixture",
    )


def build_rows() -> list[Any]:
    """Definitions the owner manifests need beyond the committed seed bundles."""

    seeded = {item.ref.logical_id: item for item in seeded_published()}
    pubmed = seeded["mcp.pubmed"].definition
    assert isinstance(pubmed, MCPServerDefinition)
    remote_pubmed = MCPServerDefinition.model_validate(
        {
            **pubmed.model_dump(mode="python"),
            "logical_id": "mcp.pubmed-remote",
            "title": "PubMed MCP behind a self-hosted Streamable HTTP endpoint",
            "description": (
                "Cloud-lane deployment of the PubMed MCP server (same tools as mcp.pubmed) "
                "behind a self-hosted Streamable HTTP endpoint, for cursor_cloud."
            ),
            "transport": "streamable_http",
            "endpoint": "https://pubmed-mcp.fixture.invalid/mcp",
            "launch_template": None,
            "host_support": _support(*ALL_LANES),
            "env": {},
            "package_pin": None,
        }
    )
    kg_server = MCPServerDefinition.model_validate(
        {
            **pubmed.model_dump(mode="python"),
            "logical_id": "mcp.biotech-kg",
            "title": "Biotech knowledge graph ingestion server (fixture stand-in)",
            "description": (
                "Stand-in for the Biotech knowledge-graph capability: applies claim ingestion "
                "intents and returns receipts (noop_echo-backed in tests)."
            ),
            "allowed_tools": frozenset({"kg_ingest"}),
            "secret_refs": (),
            "env_refs": {},
            "host_support": _support(LaneProfile.DEEP_AGENTS, LaneProfile.CURSOR_LOCAL),
            "tools": (),
        }
    )
    kg_server_ref = _published(kg_server).ref
    kg_tool = MCPToolDefinition(
        logical_id="mcp.biotech-kg.tool.kg-ingest",
        title="kg_ingest",
        description="Knowledge graph ingestion of accepted claims with provenance receipts.",
        server_ref=kg_server_ref,
        tool_name="kg_ingest",
        input_schema={"type": "object"},
        schema_digest=_digest("kg_ingest"),
        side_effect_class="bounded_write",
    )
    agent_browser_skill = _skill(
        "skill.agent-browser",
        "agent-browser browser automation skill",
        "Drive a real browser with agent-browser: open, snapshot, click, fill, screenshot.",
        version="0.4.0",
        lanes=(LaneProfile.DEEP_AGENTS, LaneProfile.CURSOR_LOCAL),
    )
    browser_mcp = seeded["mcp.agent-browser"]
    plugin = PluginDefinition(
        logical_id="plugin.agent-browser",
        title="agent-browser browser automation plugin",
        description=(
            "agent-browser browser automation bundle: the agent-browser skill and its MCP server."
        ),
        manifest=PluginManifest(
            members=(
                PluginMember(
                    pin=capability_pin(_published(agent_browser_skill)),
                    role=PluginMemberRole.SKILL,
                ),
                PluginMember(pin=capability_pin(browser_mcp), role=PluginMemberRole.MCP_SERVER),
            )
        ),
        host_support=_support(LaneProfile.DEEP_AGENTS, LaneProfile.CURSOR_LOCAL),
    )
    return [
        _skill(
            "skill.mission-control-observe",
            "Mission Control observe",
            "Observe Mission Control runs: inspect, transcript, events watch and chain inspect.",
            version="0.2.0",
            lanes=ALL_LANES,
        ),
        _skill(
            "skill.biotech-literature-review",
            "Biotech literature review procedure",
            "Biotech literature review procedure: search, screen, extract claims, cite.",
            version="1.0.0",
            lanes=ALL_LANES,
        ),
        _skill(
            "context.biotech-schema-muscle-aging",
            "Biotech schema context: muscle aging",
            "Biotech schema context bundle for muscle aging entities and claim fields.",
            version="1.0.0",
            lanes=ALL_LANES,
        ),
        agent_browser_skill,
        remote_pubmed,
        kg_server,
        kg_tool,
        _hook(
            "hook.citation-check",
            "Citation presence check",
            "Citation presence check: every new claim line carries a resolvable citation.",
            events=(HookEvent.AFTER_TOOL, HookEvent.AFTER_FILE_EDIT, HookEvent.STOP),
            lanes=ALL_LANES,
        ),
        _hook(
            "hook.shell-policy",
            "Shell command policy",
            "Shell command policy: deny destructive shell commands before they run.",
            events=(HookEvent.BEFORE_SHELL,),
            lanes=(LaneProfile.DEEP_AGENTS, LaneProfile.CURSOR_LOCAL, LaneProfile.CURSOR_CLOUD),
            fail_closed=True,
        ),
        _subagent(
            "subagent.literature-verifier",
            "Literature verifier subagent",
            "Literature verifier subagent: checks claims against cited sources, read only.",
            lanes=ALL_LANES,
        ),
        _subagent(
            "subagent.code-verifier",
            "Code verifier subagent",
            "Code verifier subagent, readonly: reviews a diff against the issue text.",
            lanes=ALL_LANES,
        ),
        plugin,
        _tool(
            "assessment.evidence-coverage",
            "Evidence coverage assessment",
            "Evidence coverage assessment of a claim table against the included studies.",
        ),
        _tool(
            "assessment.code-change-verification",
            "Code change verification",
            "Code change verification against issue acceptance criteria.",
        ),
        _tool(
            "executor.claim-schema-validation",
            "Claim schema validation",
            "Claim schema validation deterministic executor for claim tables.",
        ),
        _tool(
            "executor.test-run",
            "Test run",
            "Run the declared test command and capture a test report.",
        ),
        _tool(
            "executor.git-snapshot",
            "Git snapshot",
            "Record the branch commit snapshot as a git ref artifact.",
        ),
    ]


def write_seeds() -> None:
    rows = [row.model_dump(mode="json") for row in build_rows()]
    SEEDS.write_text(
        json.dumps({"schema": "mc.fast_track_fixture_catalog.v1", "definitions": rows}, indent=1)
        + "\n",
        encoding="utf-8",
        newline="\n",
    )


def fixture_definitions() -> list[Any]:
    document = json.loads(SEEDS.read_text(encoding="utf-8"))
    return [DEFINITION_ADAPTER.validate_python(item) for item in document["definitions"]]


async def fast_track_catalog() -> tuple[InMemoryDefinitionRepository, CapabilitySearchService]:
    """The seeded catalog plus the fixture rows, projected lexically (no embeddings)."""

    definitions = InMemoryDefinitionRepository()
    refs = []
    for item in seeded_published():
        published = await definitions.publish(item.definition, "seed", NOW, 0)
        refs.append(published.ref)
    seeded = {(ref.kind, ref.logical_id) for ref in refs}
    for definition in fixture_definitions():
        if (definition.kind, definition.logical_id) in seeded:
            continue  # a production seed (A6/A7) supersedes the fixture stand-in
        published = await definitions.publish(definition, "fixture", NOW, 0)
        refs.append(published.ref)
    search = InMemoryCatalogSearchRepository()
    projector = CatalogProjector(
        definitions=definitions,
        search=search,
        embeddings=None,
        embedding_model_id="text-embedding-3-small",
        embedding_dimensions=1536,
        projection_generation="fast-track-fixture-1",
        clock=lambda: NOW,
    )
    await projector.project_many(tuple(CatalogProjectionInput(ref=ref) for ref in refs))
    return definitions, CapabilitySearchService(search=search, definitions=definitions)


if __name__ == "__main__":
    write_seeds()
